404	                        let cuts = list
405	                            .cuts
406	                            .iter()
407	                            .map(|&(row, field, removed)| crate::toon::table::Cut {
408	                                section: name,
409	                                row,
410	                                field: fields.get(field).map_or("", String::as_str),
411	                                removed,
412	                            })
413	                            .collect();
414	                        (Part::ok(name, list.text, cuts, total), list.extra_hint.map(Hint::new))
415	                    }
416	                    Err(e) => (Part::failed(name, "toon_validation_failed", e.to_string()), None),
417	                }
418	            }
419	            SectionBody::Kv(items) => (kv_part(name, items, total), None),
420	            // One string value under the section's name, escaped like any other value: prose cannot start a line
421	            // of its own, so it cannot forge a `help[]` line or break the document.
422	            SectionBody::Text { text, .. } => {
423	                let line = format!("{}: {}", crate::toon::escape_key(name), crate::toon::escape_value(text));
424	                (Part::ok(name, line, Vec::new(), total), None)
425	            }
426	        }
427	    }
428	
429	    /// Whether each block fails validation, without rendering it.
430	    fn failed_flags(&self) -> Vec<bool> {
431	        self.blocks()
432	            .iter()
433	            .map(|s| match s.body() {
434	                SectionBody::Toon { fields, rows } => {
435	                    ToonDocument::validate_list(self.list_ref(s.name(), fields, rows)).is_err()
436	                }
437	                SectionBody::Kv(items) => crate::kv::validate_keys(items).is_err(),
438	                SectionBody::Text { .. } => false,
439	            })
440	            .collect()
441	    }
442	
443	    /// The first key the body cannot render, or `None`. Sections render as root keys (a TOON list or text section
444	    /// under its name, a KV section as its item keys), beside the keys michi writes itself
445	    /// ([`crate::toon::RESERVED_ROOT_KEYS`]: the envelope blocks, the keys that follow a body, and the error
446	    /// document's keys). The reserved names are claimed whether or not michi writes that block here, so validity
447	    /// never depends on the caller's data, and a success response cannot carry `error:` or `message:` lines.
448	    /// `failed[i]` says whether block `i` failed validation: it writes no keys here, because its failure joins the
449	    /// one `error` object as a cause (see [`body`](Self::body)), so any number of failed blocks is no collision.
450	    /// Provenance labels sit one level down (see [`crate::provenance::label_collision`]).
451	    fn root_collision(&self, failed: &[bool]) -> Option<String> {
452	        let blocks = self.blocks();
453	        let mut seen: std::collections::HashSet<&str> = crate::toon::RESERVED_ROOT_KEYS.into_iter().collect();
454	        for (s, failed) in blocks.iter().zip(failed) {
455	            if *failed {
456	                continue;
457	            }
458	            let keys: Vec<&str> = match s.body() {
459	                SectionBody::Toon { .. } | SectionBody::Text { .. } => vec![s.name()],
460	                SectionBody::Kv(items) => items.iter().map(|i| i.key.as_str()).collect(),
461	            };
462	            for key in keys {
463	                if !seen.insert(key) {
464	                    return Some(key.to_string());
465	                }
466	            }
467	        }
468	        let p = self.provenance.as_ref()?;
469	        crate::provenance::label_collision(p).map(str::to_string)
470	    }
471	
472	    /// The body: the error block, sections, `budget:`, `provenance:`.
473	    ///
474	    /// Blocks are joined with one LF and empty ones are skipped. `truncated` and `totalCount` are root keys, so they
475	    /// may appear once: when one block has them they stay inline after its list; when two or more do, each becomes
476	    /// one table with a leading `section` column, after the last block.
477	    ///
478	    /// Validation failures of the response's own shape (every block that failed, and the first root key two blocks
479	    /// write) never hide the caller's [`DomainError`] and never hide each other: there is one error block. When the
480	    /// caller set an error it is the error block, with every failure added after its own causes
481	    /// (`toon_validation_failed: …`), and a failed block writes no lines of its own. Without a caller's error the
482	    /// first failure is the error block and the others are its causes. Either way [`Body::failures`] carries them to
483	    /// the JSON `error` object, so text and JSON report the same error.
484	    ///
485	    /// The flag is whether this response is an error: `as_error()`, `error()` or a validation failure. Every output
486	    /// surface reads its error flag from here so text, JSON and MCP never disagree.
487	    fn body(&self) -> Body<'_> {
488	        let blocks = self.blocks();
489	        let mut parts: Vec<Part<'_>> = Vec::with_capacity(blocks.len());
490	        let mut flags: Vec<bool> = Vec::with_capacity(blocks.len());
491	        let mut extras: Vec<Hint> = Vec::new();
492	        for s in blocks.iter() {
493	            let (part, extra) = self.section_part(s);
494	            flags.push(part.failure.is_some());
495	            // One line per cut response is enough: every section's line says the same thing.
496	            if let Some(h) = extra {
497	                if !extras.contains(&h) {
498	                    extras.push(h);
499	                }
500	            }
501	            parts.push(part);
502	        }
503	        // Two blocks writing one root key would be invalid TOON. Like any other bad input the whole body becomes the
504	        // visible validation error, so the caller sees it instead of a document a decoder rejects.
505	        let mut failures: Vec<Failure> = parts.iter().filter_map(|p| p.failure.clone()).collect();
506	        if let Some(key) = self.root_collision(&flags) {
507	            failures.push(Failure::collision(&key));
508	            let error = self.error_block(&failures);
509	            let text = match &error {
510	                Some(e) => {
511	                    let mut out = String::new();
512	                    crate::error::push_error_fields(&mut out, e);
513	                    out
514	                }
515	                None => failures[0].body(&failures[1..]),
516	            };
517	            return Body { text, is_error: true, extra: Vec::new(), error, failures };
518	        }
519	        let error = self.error_block(&failures);
520	        let cutters = parts.iter().filter(|p| !p.cuts.is_empty()).count();
521	        let totals = parts.iter().filter(|p| p.total.is_some()).count();
522	        let mut out = String::with_capacity(parts.iter().map(|p| p.text.len() + 24).sum::<usize>() + 256);
523	        if let Some(e) = &error {
524	            crate::error::push_error_fields(&mut out, e);
525	        }
526	        let mut lead_written = false;
527	        for p in &parts {
528	            // One `error` object per document: with the caller's error leading, every failed block is a cause of it,
529	            // and without one the first failed block writes the lines, the others being its causes.
530	            match &p.failure {
531	                None => join_block(&mut out, &p.text),
532	                Some(f) if error.is_none() && !lead_written => {
533	                    lead_written = true;
534	                    join_block(&mut out, &f.body(&failures[1..]));
535	                }
536	                Some(_) => {}
537	            }
538	            if cutters == 1 {
539	                crate::toon::table::push_truncated(&mut out, &p.cuts, false);
540	            }
541	            if let (1, Some(n)) = (totals, p.total) {
542	                join_block(&mut out, &format!("totalCount: {n}"));
543	            }
544	        }
545	        if cutters >= 2 {
546	            let cuts: Vec<crate::toon::table::Cut<'_>> = parts.iter().flat_map(|p| p.cuts.iter().cloned()).collect();
547	            crate::toon::table::push_truncated(&mut out, &cuts, true);
548	        }
549	        if totals >= 2 {
550	            use crate::toon::table::{self, Cell};
551	            table::push_header(&mut out, "totalCount", totals, ["section", "total"]);
552	            for p in &parts {
553	                if let Some(total) = p.total {
554	                    table::push_row(&mut out, &[Cell::Str(p.name), Cell::count(total)]);
555	                }
556	            }
557	        }
558	        if let Some(b) = &self.budget {
559	            join_block(&mut out, &crate::budget::render_budget_block(b, &self.sections));
560	        }
561	        if let Some(p) = &self.provenance {
562	            join_block(&mut out, &crate::provenance::render_provenance_block(p));
563	        }
564	        let is_error = !failures.is_empty() || self.is_error || error.is_some();
565	        Body { text: out, is_error, extra: extras, error, failures }
566	    }
567	
568	    /// The error block the response renders: the caller's error, with every failure added as a cause after its own
569	    /// when the response's shape also failed validation, so none hides another. `None` without a caller's error.
570	    fn error_block(&self, failures: &[Failure]) -> Option<std::borrow::Cow<'_, DomainError>> {
571	        let e = self.error.as_ref()?;
572	        Some(if failures.is_empty() {
573	            std::borrow::Cow::Borrowed(e)
574	        } else {
575	            std::borrow::Cow::Owned(failures.iter().fold(e.clone(), |e, f| e.cause(f.cause())))
576	        })
577	    }
578	
579	    /// Compose the text document: body, help block, recovery block. Each part is a TOON 4.4 document without a
580	    /// trailing newline and the append helpers join them with one LF, so the result is one root object whose keys
581	    /// are unique (the body cannot use `totalCount`, `help`, `recovery` or `truncated`). Appends to `body` in place.
582	    fn finish_text(&self, mut body: String, extra: &[Hint]) -> String {
583	        let hints = self.hints_with(extra);
584	        let recovery = self.recovery_list();
585	        if !hints.is_empty() || !recovery.is_empty() {
586	            body.reserve(1 + hints.len() * 60 + recovery.len() * 80);
587	        }
588	        crate::hints::append_hints(&mut body, &hints);
589	        crate::recovery::append_recovery(&mut body, &recovery);
590	        body
591	    }
592	
593	    /// Render the response in the requested format.
594	    #[must_use]
595	    pub fn render(&self, format: OutputFormat) -> String {
596	        match format {
597	            OutputFormat::Text => self.render_text(),
598	            OutputFormat::Json => self.render_json(),
599	        }
600	    }
601	
602	    fn render_text(&self) -> String {
603	        let body = self.body();
604	        self.finish_text(body.text, &body.extra)
605	    }
606	
607	    /// Whether this response is an error: `as_error()` or `error()` was called, or the response failed validation (a
608	    /// section's TOON rows or KV items, or two blocks writing one root key), which renders the
609	    /// `toon_validation_failed` or `kv_validation_failed` error. Validates without rendering.
610	    #[must_use]
611	    pub fn is_error(&self) -> bool {
612	        if self.is_error || self.error.is_some() {
613	            return true;
614	        }
615	        let failed = self.failed_flags();
616	        failed.contains(&true) || self.root_collision(&failed).is_some()
617	    }
618	
619	    /// Render just the `help[N]:` block: the error's hints, then the response's own.
620	    #[must_use]
621	    pub fn render_hints_only(&self) -> String {
622	        crate::hints::render_hints(&self.hints_with(&[]))
623	    }
624	
625	    /// Render for the given audience.
626	    #[must_use]
627	    pub fn render_for(&self, audience: crate::audience::Audience) -> String {
628	        match audience {
629	            crate::audience::Audience::Assistant => self.render_text(),
630	            crate::audience::Audience::User => self.human_content.clone().unwrap_or_else(|| self.render_text()),
631	        }
632	    }
633	
634	    /// Whether `.human_content()` was set on this builder.
635	    #[must_use]
636	    pub fn has_human_content(&self) -> bool {
637	        self.human_content.is_some()
638	    }
639	
640	    /// Build the MCP `CallToolResult` for this response.
641	    #[must_use]
642	    pub fn to_call_tool_result(&self) -> crate::mcp::CallToolResult {
643	        let body = self.body();
644	        let structured_content = self.json_from_body(&body);
645	        let is_error = body.is_error;
646	        let mut content = vec![crate::mcp::ContentBlock {
647	            text: self.finish_text(body.text, &body.extra),
648	            audience: vec![crate::audience::Audience::Assistant],
649	        }];
650	        if let Some(human) = &self.human_content {
651	            content.push(crate::mcp::ContentBlock {
652	                text: human.clone(),
653	                audience: vec![crate::audience::Audience::User],
654	            });
655	        }
656	        crate::mcp::CallToolResult::new(
657	            content,
658	            is_error,
659	            Some(crate::mcp::JsonObject::from_trusted(structured_content)),
660	        )
661	    }
662	
663	    fn render_json(&self) -> String {
664	        self.json_from_body(&self.body())
665	    }
666	
667	    /// The JSON object. Its `error` is the error block the text leads with: the caller's error (with a validation
668	    /// failures among its causes), or the first validation failure with the others as causes, with the same four keys.
669	    fn json_from_body(&self, body: &Body<'_>) -> String {
670	        let hints = self.hints_with(&body.extra);
671	        let recovery = self.recovery_list();
672	        let capacity =
673	            body.text.len() + hints.iter().map(|h| h.as_str().len() + 16).sum::<usize>() + recovery.len() * 64 + 64;
674	        let mut out = String::with_capacity(capacity + 128);
675	        out.push_str("{\"body\":");
676	        json::push_str(&mut out, &body.text);
677	        match (&body.error, body.failures.split_first()) {
678	            (Some(e), _) => {
679	                out.push_str(",\"error\":");
680	                crate::error::push_error_json(&mut out, e);
681	            }
682	            (None, Some((lead, causes))) => {
683	                out.push_str(",\"error\":");
684	                lead.push_json(&mut out, causes);
685	            }
686	            (None, None) => {}
687	        }
688	        if !self.sections.is_empty() {
689	            out.push_str(",\"sections\":");
690	            json::push_array(&mut out, &self.sections, push_section_json);
691	        }
692	        if let Some(b) = &self.budget {
693	            out.push_str(",\"budget\":");
694	            crate::budget::push_budget_json(&mut out, b, &self.sections);
695	        }
696	        if let Some(p) = &self.provenance {
697	            out.push_str(",\"provenance\":");
698	            crate::provenance::push_provenance_json(&mut out, p);
699	        }
700	        out.push_str(",\"hints\":");
701

